M0 = 1.0
s1 = np.array([[0, 1], [1, 0]], complex); s2 = np.array([[0, -1j], [1j, 0]]); s3 = np.diag([1., -1]).astype(complex)
I2 = np.eye(2); Z2 = 0 * I2
G4 = [np.block([[Z2, -1j * s], [1j * s, Z2]]) for s in (s1, s2, s3)] + [np.block([[Z2, I2], [I2, Z2]])]
G5 = G4[0] @ G4[1] @ G4[2] @ G4[3]; E4 = np.eye(4); S2 = 1j * G4[1]; S4 = 1j * G4[3]
SPEC = [(1 / 6, 6), (-1 / 2, 2), (-2 / 3, 3), (1 / 3, 3), (1.0, 1)]      # (Y, multiplicity): Q, L, u^c, d^c, e^c
