# ---------------- machinery (luscher-m0-1 block construction) ----------------
_cache = {}
def block_static(L):
    if L in _cache: return _cache[L]
    n = 4 * L * L; X = np.zeros((n, n), complex); Xr = X.reshape(L, L, 4, L, L, 4)
    for mu in (0, 2):
        fw = (G4[mu] - E4) / 2; bw = -(G4[mu] + E4) / 2
        for x in range(L):
            for z in range(L):
                if mu == 0: Xr[x, z, :, (x + 1) % L, z, :] += fw; Xr[(x + 1) % L, z, :, x, z, :] += bw
                else: Xr[x, z, :, x, (z + 1) % L, :] += fw; Xr[x, (z + 1) % L, :, x, z, :] += bw
    for x in range(L):
        for z in range(L): Xr[x, z, :, x, z, :] += (4 - M0) * E4
    _cache[L] = X; return X
def block_q(th2, th4, p2, p4, solver="evr"):
    L = len(th2); X = block_static(L).copy(); n = 4 * L * L; ii = np.arange(L); f2 = th2 + p2; f4 = th4 + p4
    loc = (np.sin(f2)[:, None, None, None] * S2 - np.cos(f2)[:, None, None, None] * E4
           + np.sin(f4)[None, :, None, None] * S4 - np.cos(f4)[None, :, None, None] * E4)
    Xr = X.reshape(L, L, 4, L, L, 4); Xr[ii[:, None], ii[None, :], :, ii[:, None], ii[None, :], :] += loc
    H = np.einsum('st,ktn->ksn', G5, X.reshape(L * L, 4, n)).reshape(n, n)
    w, v = sl.eigh(H, driver="evr", check_finite=False) if solver == "evr" else np.linalg.eigh(H)
    return ((v.real ** 2 + v.imag ** 2) * np.sign(w)[None, :]).sum(1).reshape(L, L, 4).sum(-1), w, v
def q_full(th2, th4, T, solver="numpy"):
    ps = 2 * np.pi * np.arange(T) / T; return sum(block_q(th2, th4, a, b, solver)[0] for a in ps for b in ps) / T ** 2
def reps(T, diag): h = T // 2; return [(a, b) for a in range(h + 1) for b in range(h + 1) if (not diag or a <= b)]
def q_reduced(th2, th4, T, diag):
    """pi rotations in (1,2), (3,4): block (-p2,p4) = block(p2,p4) at x1 -> 1-x1, etc.; diagonal: (13)(24) swap."""
    L = len(th2); R = (1 - np.arange(L)) % L; q = np.zeros((L, L)); dev = 0.0
    for j2, j4 in reps(T, diag):
        Q = block_q(th2, th4, 2 * np.pi * j2 / T, 2 * np.pi * j4 / T)[0]; im = {}
        for s2_ in (0, 1):
            for s4_ in (0, 1):
                for sw in ((0, 1) if diag else (0,)):
                    a, b, M = j2, j4, Q
                    if s2_: a, M = (-a) % T, M[R, :]
                    if s4_: b, M = (-b) % T, M[:, R]
                    if sw: a, b, M = b, a, M.T
                    if (a, b) in im: dev = max(dev, np.abs(im[(a, b)] - M).max())
                    else: im[(a, b)] = M
        q += sum(im.values())
    return q / T ** 2, dev
def odd_profile(L, n, a):
    x = np.arange(L); p = 2 * np.pi * n / L; return a * np.sin(p * (x - 0.5)) / (2 * np.sin(p / 2))
def max_plaq_dev(th2, th4):
    F_ = np.concatenate([np.roll(th2, -1) - th2, np.roll(th4, -1) - th4]); return float(np.abs(1 - np.exp(1j * F_)).max())
def r_coef(q, n, m, a):
    L = q.shape[0]; x = np.arange(L); p = 2 * np.pi * n / L; k = 2 * np.pi * m / L
    return 4 * (q * np.exp(-1j * (p * x[:, None] + k * x[None, :]))).sum() / L ** 2 / a ** 2 * np.exp(1j * (p + k) / 2)
def build_H_full(th):
    L = round(th.shape[1] ** 0.25); N = L ** 4; idx = np.arange(N).reshape((L,) * 4); xs = np.arange(N)
    H = np.zeros((4 * N, 4 * N), complex); H4 = H.reshape(N, 4, N, 4); H4[xs, :, xs, :] += (4 - M0) * G5
    for mu in range(4):
        sh = np.roll(idx, -1, axis=mu).reshape(-1); U = np.exp(1j * th[mu])
        H4[xs, :, sh, :] += U[:, None, None] * (G5 @ (G4[mu] - E4) / 2)
        H4[sh, :, xs, :] += U.conj()[:, None, None] * (-G5 @ (G4[mu] + E4) / 2)
    return H

