crit("G1 [admissibility] every job has max_p |1 - U_p| < 1/30 (Hernandez-Jansen-Luscher locality bound, supplied)",
     pl < BOUND and an < BOUND, f"max over {len(DATA['r'])} jobs {pl:.5f}, analytic {an:.5f}, bound {BOUND:.5f}")

# ---------- the 16's coefficient: R16(eps) = sum m Y^3 r(|Y| eps); joint fit R16/eps^2 = c4 + c6 eps^2 ----------
def R16(L, T, n, m, e):
    vals = [r_of(L, T, n, m, round(abs(Y) * 6 * e)) for Y, _ in SPEC]
    return None if None in vals else sum(mu * Y ** 3 * r for (Y, mu), r in zip(SPEC, vals))
def RL(L, T, n, m, e):
    r = r_of(L, T, n, m, 3 * e); return None if r is None else -r / 4
def fit46(L, T, n, m):
    y = [R16(L, T, n, m, e) for e in EPS]
    if None in y: return None
    E2 = np.array([(e / 100) ** 2 for e in EPS]); Y_ = np.array(y) / E2
    A_ = np.vstack([np.ones(3), E2]).T; c, *_ = np.linalg.lstsq(A_, Y_, rcond=None)
    return c[0], c[1], float(np.abs(A_ @ c - Y_).max()), y
def ph(L, n): return 2 * np.sin(np.pi * n / L)
def sv(L, n): return np.sin(np.pi * n / L) ** 2
H = {T: [fit46(24, T, n, n) for n in (1, 2, 3)] for T in (24, 32)}
print("L = 24 diagonal (n = 1, 2, 3; |p_hat| 0.261, 0.518, 0.765): c4, c6, fit residual/|c4|, R16(eps = 0.01, 0.02, 0.03):")
for T in (24, 32):
    print(f"  T={T}: " + "; ".join(f"c4 {c[0]:+.3e} c6 {c[1]:+.2e} res {c[2]/abs(c[0]):.0e}" for c in H[T]))
print("  R16 T=32: " + "; ".join(" ".join(f"{r:+.2e}" for r in c[3]) for c in H[32]))
resN = max(c[2] / abs(c[0]) for T in H for c in H[T])
crit("N [noise/truncation] at every L = 24 point the one-dof residual of the joint fit <= 5% of |c4|", resN <= 0.05,
     f"max residual/|c4| {resN:.1e}")
def expo(cs, L, ns):
    c4 = np.array([c[0] for c in cs]); one = bool(np.all(c4 > 0) or np.all(c4 < 0))
    return one, np.polyfit(np.log([ph(L, n) for n in ns]), np.log(np.abs(c4)), 1)[0]
