# ---------- P5, P5b, D: L = 12 grid + L = 16 points (T = 24) ----------
def symfit(svals, tvals, y, deg):
    X = np.array([[a ** u * b ** v + a ** v * b ** u for u in range(deg + 1) for v in range(u, deg + 1 - u)]
                  for a, b in zip(svals, tvals)])
    c, *_ = np.linalg.lstsq(X, y, rcond=None); return 2 * c[0], np.abs(X @ c - y).max()
pts = [(12, n, m) for n in range(1, 6) for m in range(1, 6)] + [(16, n, m) for (n, m) in
       ((1, 1), (2, 2), (3, 3), (4, 4), (1, 2), (2, 1), (1, 3), (3, 1))]
C4 = {p: fit46(p[0], 24, p[1], p[2]) for p in pts}; C4 = {p: v for p, v in C4.items() if v is not None}
S_ = [sv(p[0], p[1]) for p in C4]; T_ = [sv(p[0], p[2]) for p in C4]
c0, rr = symfit(S_, T_, np.array([C4[p][0] for p in C4]), 3); mx = max(abs(v[0]) for v in C4.values())
e16 = np.log(C4[(16, 2, 2)][0] / C4[(16, 1, 1)][0]) / np.log(ph(16, 2) / ph(16, 1))
