amps = np.array([1, 2, 3, 4, 6, 8, 9, 12, 18]) / 600
def r4fit(L, T, n):
    y = np.array([r_of(L, T, n, n, k) for k in (1, 2, 3, 4, 6, 8, 9, 12, 18)])
    A_ = np.vstack([np.ones(9), amps ** 2, amps ** 4]).T; c, *_ = np.linalg.lstsq(A_, y, rcond=None)
    return c, np.abs(A_ @ c - y).max()
